// Prepara la richiesta all'LLM con l'evento ricevuto da Casa
const evento = $input.first().json.body;
const sistema = "Sei l'assistente di una casa condivisa. Ricevi le faccende ancora da fare questa settimana, chi le fa, i minuti di lavoro di ciascuno e i vincoli. Dopo un cambio dei giorni in sede, proponi AL MASSIMO 5 modifiche semplici per riequilibrare il carico: spostare una faccenda a un altro momento della stessa settimana (campo quando, ISO 8601 con fuso orario) oppure passarla per questa volta all'altra persona (campo chi). Rispetta sempre le regole ricevute: niente durante il sabato, niente a chi è fuori casa o ha un impegno, non cambiare persona alle faccende 'insieme' e non toccare quelle legate alla sede. Se il carico è già equilibrato, rispondi con un elenco vuoto. Scrivi il motivo di ogni proposta in italiano, in una frase.";
const schema = {
  "type": "object",
  "properties": {
    "proposte": {
      "type": "array",
      "maxItems": 5,
      "items": {
        "type": "object",
        "properties": {
          "choreId": {
            "type": "integer"
          },
          "chi": {
            "type": "string"
          },
          "quando": {
            "type": "string"
          },
          "motivo": {
            "type": "string"
          }
        },
        "required": [
          "choreId",
          "motivo"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "proposte"
  ],
  "additionalProperties": false
};
return [{
  json: {
    model: 'qwen3.5:4b',
    temperature: 0.2,
    reasoning_effort: 'low',
    messages: [
      { role: 'system', content: sistema },
      { role: 'user', content: JSON.stringify(evento) },
    ],
    response_format: { type: 'json_schema', json_schema: { name: 'proposte', schema } },
  },
}];

// La risposta dell'LLM è un JSON in choices[0].message.content: se non si legge, nessuna proposta
const risposta = $input.first().json;
let proposte = [];
try {
  proposte = JSON.parse(risposta.choices?.[0]?.message?.content ?? '{}').proposte ?? [];
} catch (e) {
  proposte = [];
}
const evento = $('Evento da Casa').first().json.body;
return [{ json: { settimana: evento.settimana, proposte } }];
